import{z as i,x as A,o as r,c as d,q as t,j as o,D as E,d as e,s,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"央行资产负债表","description":"","frontmatter":{"title":"央行资产负债表","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/central-bank-balance-sheet.md","filePath":"econ/central-bank-balance-sheet.md","lastUpdated":1791413859000}'),p={name:"econ/central-bank-balance-sheet.md"};function c(h,a,m,f,C,u){const B=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="央行资产负债表" tabindex="-1">央行资产负债表 <a class="header-anchor" href="#央行资产负债表" aria-label="Permalink to &quot;央行资产负债表&quot;">​</a></h1><div class="epigraph"><p>政策利率撞上零之后，工具变成规模、久期与对手方。资产负债表是非常规货币的会计，不是装饰。</p><footer>—— Bernanke, The Federal Reserve and the Financial Crisis；对照 Curdia and Woodford 对 QE 的理论讨论</footer></div><p><a href="/econ/shadow-run">上一课</a>把停滚写进回购与 ABCP。缺口是谁在停滚之后持有那些资产：央行扩表。本课钉资产负债表；回购与 MMF 的制度下一课再拆。不重写 Leeper 的主动被动，只补工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统工具是短期政策利率。碰到<a href="/econ/zlb-unconventional">零下限</a>或储备转充裕之后，走廊要靠 IOER/ON RRP 一类地板，数量与久期变成独立维度。QE：买长债压期限溢价；信贷宽松：买或担保私人资产。若只把扩表写成「印钱」，会把储备、财政债和信用风险混成一个 \\(M\\)。缺口是分清资产侧（谁的债）和负债侧（储备 vs 现金 vs 逆回购）：每一项都带自己的信用、久期与对手方标签，混在一起读不出政策做了什么。</p><p><span class="marginnote">把两个词翻译开：QE 是「换久期」——用新造的储备把市场手里的长期债换走，压的是期限溢价；信贷宽松是「换信用」——直接买或担保私人资产（如 MBS），压的是信用利差。两者动的是资产负债表的不同刻度，只说「印钱」会把它们混成一锅。</span></p><p><span class="marginnote">Gertler and Karadi 把央行信贷政策放进中介模型。Krishnamurthy and Vissing-Jorgensen 的 QE 事件研究。Reis 对央行资本与再分配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一张表：资产（国债、MBS、贷款）、负债（现金、储备、政府存款、ON RRP）、资本。政策实验各动一边：扭转操作只换资产侧久期、不动规模；QE 换规模为主、久期为辅；对手方资格换的是谁能借到央行的价。退出：缩表与付息储备是同一套走廊的另一侧。与财政主导：付息储备把货币负债变成类国债，主导问题更贴预算（<a href="/econ/fiscal-monetary-dominance">财政与货币主导</a>）。非常规政策的信号与承诺面见<a href="/econ/qe-forward-guidance">QE 与前瞻指引</a>，本课只管表。</p>',9)),(r(),o(l,null,{default:E(()=>[s(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASSET%5B%22%E5%9B%BD%E5%80%BA%20%2F%20MBS%20%2F%20%E4%BF%A1%E8%B4%B7%22%5D%20--%3E%20SIZE%5B%22%E8%A7%84%E6%A8%A1%E4%B8%8E%E4%B9%85%E6%9C%9F%22%5D%0A%20%20LIAB%5B%22%E5%82%A8%E5%A4%87%20%2F%20RRP%22%5D%20--%3E%20FLOOR%5B%22%E5%88%A9%E7%8E%87%E5%9C%B0%E6%9D%BF%22%5D%0A%20%20SIZE%20--%3E%20TP%5B%22%E6%9C%9F%E9%99%90%E6%BA%A2%E4%BB%B7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[e("QE 的组合平衡：长期安全资产被抽走，私人要再平衡到其他久期，压 \\(r^L\\)（Vayanos–Vila 的首选生境）。机制要落在容量上：久期被央行收走后总得有人持有——要么本来愿意承接久期的储蓄者（生境被填补），要么受风险预算约束的套利者。套利者的资产负债表是稀缺品，供给一点一点往里塞，期限溢价就一点一点往下走。KVJ 的事件研究把效应拆开读：MBS 与代理债的利差缩得最多，国债期限溢价次之——买什么比买多少更早显形。信贷政策直接替换中介的 \\(\\phi\\)：买或担保私人资产，等于替中介扛下风险预算里最贵的那一段，GK 的模型里这正是乘数的来源。负债侧付息使「数量」不再一对一决定隔夜利率：IOR 给准备金一个下限价，ON RRP 把下限延伸到非银现金池，隔夜利率被钉在工具利率附近——操作几何见先修"),n("a",{href:"/econ/ior-corridor-floor"},"准备金利息与走廊"),e("，这里记住一句：地板系统里立场在利率上，规模是副产品。")],-1)),(r(),o(l,null,{default:E(()=>[s(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%A4%AE%E8%A1%8C%E4%B9%B0%E5%85%A5%E9%95%BF%E6%9C%9F%E5%80%BA%22%5D%20--%3E%20T%5B%22%E5%B8%82%E5%9C%BA%E6%89%8B%E4%B8%AD%E7%9A%84%E9%95%BF%E4%B9%85%E6%9C%9F%E8%B5%84%E4%BA%A7%E8%A2%AB%E6%8A%BD%E8%B5%B0%22%5D%0A%20%20T%20--%3E%20R%5B%22%E7%BB%84%E5%90%88%E5%86%8D%E5%B9%B3%E8%A1%A1%EF%BC%9A%E6%94%B9%E4%B9%B0%E5%85%B6%E4%BB%96%E4%B9%85%E6%9C%9F%E4%B8%8E%E8%B5%84%E4%BA%A7%22%5D%0A%20%20R%20--%3E%20P%5B%22%E6%9C%9F%E9%99%90%E6%BA%A2%E4%BB%B7%E4%B8%8E%E9%95%BF%E6%9C%9F%E5%88%A9%E7%8E%87%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20P%20--%3E%20I%5B%22%E4%BF%A1%E8%B4%B7%E3%80%81%E6%8A%95%E8%B5%84%E4%B8%8E%E8%B5%84%E4%BA%A7%E4%BB%B7%E6%A0%BC%E5%8F%97%E6%8F%90%E6%8C%AF%22%5D%0A%20%20A%5B%22%E5%A5%97%E5%88%A9%E8%80%85%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E6%9C%89%E9%99%90%22%5D%20--%3E%20R%0A%20%20A%20--%3E%20L%5B%22%E4%BE%9B%E7%BB%99%E6%8C%81%E7%BB%AD%E5%A1%9E%E5%85%A5%EF%BC%8C%E6%BA%A2%E4%BB%B7%E9%80%90%E6%AE%B5%E5%8E%8B%E7%BC%A9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">直觉类比：首选生境理论把投资者想成各有固定「车位偏好」的司机——养老金非要长债车位，货基只肯停隔夜车位。央行把长债车位的供给抽走后，长债的「租金」（期限溢价）随之下降，其他司机被迫挪位填补。传导不靠「钱变多」，靠的是有人被仓位约束逼着换位。</span></p><p>退出是同一张表倒着读。缩表不做主动卖出，用上限递增的被动赎回：到期不再全额再投资，上限分月抬到目标位，节奏提前公布让市场定价预期。2017 与 2022 两轮都是这个模板。地板系统决定了缩表的传导点在准备金供给：充足带上隔夜利率贴着 IOR，缩表不动利率；一旦准备金落到需求曲线的陡峭段，价格开始对量敏感——2019 年 9 月的脱锚是最近的例子，下一课展开。所以退出盯两个仪表：准备金离「充足」多远，短端利率贴 IOR 多紧。MBS 的赎回还受利率路径内生驱动（再融资与搬家），央行只能控制上限，控制不了实际速度。</p><p><span class="marginnote">代入数字看「被动赎回」：设每月国债赎回上限 600 亿美元，某月恰好有 800 亿到期，央行只让 600 亿回笼、其余 200 亿照常再投资——市场看到的缩表速度是公布的上限，而非到期总量。上限逐月抬升、节奏提前公布，为的是让缩表在到达「充足」底线前就被预期消化，而不是像 2019 年那样撞上陡峭段。</span></p><p><span class="marginnote">付息本身也是财政事件：资产端票息减 IOR 利息支出，决定央行利润上缴。规模大时利差的凸性暴露也大——利率上行年上缴可以转负，这就是 Reis 讲的央行资本问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估某一次 QE 的乘数点估计：事件窗口窄、横截面异质，点估计不是可以搬进 DSGE 的结构参数。下一课把负债侧的 ON RRP 与 MMF、回购连成同一套短债生态。不把 CBDC 当已落地的负债科目。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扩表要分资产侧信用/久期与负债侧地板工具。</li><li>QE 走组合平衡与中介约束：生境、风险预算、\\(\\phi\\)，不是单纯 \\(M\\)。</li><li>缩表是被动赎回加递增上限，传导点在准备金供给，不在利率宣言。</li><li>出处：Bernanke 危机讲义；KVJ 事件研究；Gertler–Karadi。</li></ul>',8))])}const _=i(p,[["render",c]]);export{F as __pageData,_ as default};
